def solve(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

def solve(line):
    fields = []
    cur = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                # look ahead for double quote escape
                if i + 1 < n and line[i+1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    in_quotes = False
                # do not add quote char itself (unless escaped)
            else:
                cur.append(c)
        else:
            if c == ',':
                fields.append(''.join(cur))
                cur = []
            elif c == '"':
                in_quotes = True
            else:
                cur.append(c)
        i += 1
    # end while
    fields.append(''.join(cur))
    return fields

