            if val == 0:
                continue
            # build submatrix without row 0 and column col
            sub = [row[:col] + row[col+1:] for row in matrix[1:]]
            sign = -1 if col % 2 else 1
            total += sign * val * det(sub)
        return total
    return det(mat)

