def solve(mat):
    """Return determinant of an integer square matrix.
    An empty matrix has determinant 1.
    Uses Laplace expansion recursively which is sufficient for the
    expected input sizes.
    """
    if not mat:
        return 1
    n = len(mat)
    if n == 1:
        return mat[0][0]
    # Recursive helper
    def det(matrix):
        size = len(matrix)
        if size == 0:
            return 1
        if size == 1:
            return matrix[0][0]
        if size == 2:
            return matrix[0][0]*matrix[1][1] - matrix[0][1]*matrix[1][0]
        total = 0
        for col, val in enumerate(matrix[0]):
            if val == 0:
                continue
            # build submatrix without first row and current column
            sub = [row[:col] + row[col+1:] for row in matrix[1:]]
            sign = -1 if col % 2 else 1
            total += sign * val * det(sub)
        return total
    return det(mat)

