def solve(weights, values, capacity):
    # 0/1 knapsack dynamic programming by capacity
    if capacity < 0:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

