def solve(s):
    """Return True if s is a valid IPv4 address.
    Conditions: four decimal numbers 0-255, no leading zeros unless the number is exactly 0.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        # No leading zeros unless single '0'
        if len(p) > 1 and p[0] == '0':
            return False
        num = int(p)
        if not (0 <= num <= 255):
            return False
    return True

