def solve(coins, amount):
    # DP for unbounded knapsack (coin change)
    if amount < 0:
        return -1
    # Initialize dp array with large number
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

# public tests
