def solve(grid):
    """Count islands in a grid with possible ragged rows.
    An island is a group of orthogonally adjacent cells with value 1.
    Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited matches each row's length
    visited = [ [False] * len(grid[i]) for i in range(rows) ]

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < len(grid[r])

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if in_bounds(ni, nj) and not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))

    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

