def solve(n, edges):
    if n <= 0:
        return []
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        adj[a].append(b)
        indeg[b] += 1
    if any(d > 0 for d in indeg):
        return []
    res = []
    heap = [0]
    removed = [False] * n
    while heap:
        u = heapq.heappop(heap)
        res.append(u)
        removed[u] = True
        for v in sorted(adj[u]):
            if removed[v]:
                return []
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    return res
