def solve(tokens):
    """Evaluate Reverse Polish Notation with integer arithmetic.
    Division truncates toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division truncating toward zero
                # Use absolute division to avoid float inaccuracies
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a * b) < 0 else 1
                res = abs(a) // abs(b)
                res = sign * res
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

